import java.util.*;
import java.io.*;

public class Main {
    static final int mod = 1000000007;

    static int add(int a, int b) {
        a += b;
        if (a >= mod) a -= mod;
        return a;
    }

    static int mult(int a, int b) {
        long t = 1L * a * b;
        if (t >= mod) t %= mod;
        return (int) t;
    }

    static int dec(int a, int b) {
        a -= b;
        if (a < 0) a += mod;
        return a;
    }

    static int power(int a, int b) {
        int out = 1;
        while (b > 0) {
            if ((b & 1) == 1) out = mult(out, a);
            a = mult(a, a);
            b >>= 1;
        }
        return out;
    }

    static int lowbit(int x) {
        return x & (-x);
    }

    static int n;
    static int[][] a = new int[10][10];
    static int[][] ch = new int[70010][128];
    static int[] q = new int[10][128];
    static int[] dp = new int[70010];
    static Map<BitSet, Integer> id = new HashMap<>();
    static int idcnt = 0;

    static int dfs(BitSet s) {
        if (id.containsKey(s))
            return id.get(s);
        idcnt++;
        id.put(s, idcnt);
        for (int i = 0; i < (1 << n); i++) {
            BitSet tmp = (BitSet) s.clone();
            for (int j = 0; j < (1 << n); j++) {
                if (!tmp.get(j)) {
                    int x = i & j;
                    while (x != 0) {
                        int t = lowbit(x);
                        if (s.get(j ^ (int) (Math.log(t) / Math.log(2)))) {
                            tmp.set(j);
                            break;
                        }
                        x -= t;
                    }
                }
            }
            ch[id.get(s)][i] = dfs(tmp);
        }
        return id.get(s);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n = Integer.parseInt(br.readLine().trim());
        dfs(new BitSet()); // Initialize DFS with empty set

        for (int i = 0; i < n; i++) {
            String[] parts = br.readLine().trim().split("\\s+");
            for (int j = 0; j < n; j++) {
                a[i][j] = mult(Integer.parseInt(parts[j]), power(100, mod - 2));
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < (1 << n); j++) {
                q[i][j] = 1;
                for (int k = 0; k < n; k++) {
                    if (((j >> k) & 1) == 1) {
                        q[i][j] = mult(q[i][j], a[i][k]);
                    } else {
                        q[i][j] = mult(q[i][j], dec(1, a[i][k]));
                    }
                }
            }
        }

        int[] dpPrev = new int[70010];
        int[] dpCurr = new int[70010];
        Arrays.fill(dpPrev, 0);
        Arrays.fill(dpCurr, 0);
        dpPrev[1] = 1;

        for (int i = 1; i <= n; i++) {
            Arrays.fill(dpCurr, 0);
            for (int j = 1; j <= idcnt; j++) {
                for (int k = 0; k < (1 << n); k++) {
                    int index = ch[j][k];
                    dpCurr[index] = add(dpCurr[index], mult(dpPrev[j], q[i - 1][k]));
                }
            }
            int[] temp = dpPrev;
            dpPrev = dpCurr;
            dpCurr = temp;
        }

        BitSet bt = new BitSet(n);
        for (int i = 0; i < (1 << n); i++) {
            bt.set(i);
        }
        int result = dpPrev[id.get(bt)];
        System.out.println(result);
    }
}
